"앞으로 한 걸음 나와 로프를 머리 위로 들어 올리고, 팔꿈치를 굽혀 손이 머리 뒤에, 팔 윗부분은 귀 옆에 오게 합니다.",
"팔꿈치를 완전히 펴서 팔을 머리 위로 곧게 뻗습니다.",
"로프를 컨트롤하며 다시 머리 뒤로 내려 팔꿈치를 굽힌 시작 자세로 돌아갑니다.",
