"바를 천천히 내려 팔이 완전히 펴진 자세로 돌아가며 충분한 스트레치를 느낍니다.",
"프리처 벤치에서는 내리는 동작(이심성 수축)이 특히 효과적이니, 중량을 툭 떨어뜨리려는 유혹을 참으세요."
